/* harmony default export */ __webpack_exports__["default"] = ({
  mixins: [],
  onLoad(e) {
    this.id = e.id || e.goods_id || '';
    let invite_id = e.invite_id || '';
    if (e.scene) {
      const scene = decodeURIComponent(e.scene);
      let goods_id = this.$util.getQueryString('goods_id', scene);
      if (goods_id) {
        this.id = goods_id;
      }
      invite_id = this.$util.getQueryString('invite_id', scene) || invite_id;
    }
    if (invite_id) {
      this.$u.vuex('vuex_invite_id', invite_id);
    }
    this.getGoodsInfo();
  },
  onShow() {
    if (this.vuex_token) {
      this.getCartNums();
    }
  },
  computed: {
    noComment() {
      return item => {
        if (!item) {
          return true;
        } else if (!item.length) {
          return true;
        } else {
          return false;
        }
      };
    },
    skuSpecAttr() {
      let arr = [];
      if (this.info.sku_spec) {
        for (let sku of this.info.sku_spec) {
          let valArr = sku.sku_value.map(item => {
            return item.title;
          });
          arr.push(sku.title + ':' + valArr.join(','));
        }
      }
      return arr.join('-');
    }
  },
  data() {
    return {
      info: {},
      id: '',
      cart_nums: 0,
      show: false,
      guarantee_show: false,
      sceneval: 2,
      loading: true,
      swiperIndex: 0,
      showReplay: false,
      replyId: '',
      showShare: false,
      showPoster: false,
      showCoupon: false,
      recommends: []
    };
  },
  methods: {
    swiperChange(index) {
      this.swiperIndex = index;
    },
    getGoodsInfo() {
      if (!this.id) {
        return;
      }
      this.$api.getGoodsInfo({
        id: this.id
      }).then(res => {
        if (res.code == 1) {
          this.info = res.data;
          this.$u.mpShare = {
            title: res.data.title,
            imageUrl: res.data.image,
            path: '/pages/goods/detail?id=' + this.id + '&invite_id=' + (this.vuex_user.id || '')
          };
          this.loading = false;
          //取同类推荐商品
          this.getGoods(this.info.category_id);
        } else {
          this.$u.toast(res.msg);
          setTimeout(() => {
            uni.$u.route({
              type: 'back'
            });
          }, 1500);
        }
      });
    },
    goIndexPage() {
      uni.reLaunch({
        url: '/pages/index/index'
      });
    },
    getCartNums() {
      this.$api.cart_nums().then(res => {
        if (res.code) {
          this.cart_nums = res.data || 0;
        }
      });
    },
    optionCollect() {
      this.$api.optionCollect({
        goods_id: this.id
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code) {
          this.$set(this.info, 'is_collect', !this.info.is_collect);
        }
      });
    },
    preview(images, index) {
      uni.previewImage({
        urls: images,
        current: index,
        longPressActions: {
          itemList: ['发送给朋友', '保存图片', '收藏'],
          success: function (data) {
            console.log('选中了第' + (data.tapIndex + 1) + '个按钮,第' + (data.index + 1) + '张图片');
          },
          fail: function (err) {
            console.log(err.errMsg);
          }
        }
      });
    },
    getGoods(category_id) {
      this.$api.getGoodsList({
        category_id
      }).then(({
        code,
        data: res,
        msg
      }) => {
        if (code == 1) {
          this.recommends = res.data;
        }
      });
    }
  }
});
